// ============================================================
// app.js — Product Catalog, Spotlight & Storefront Logic
// ------------------------------------------------------------
// PRODUCTS and SPOTLIGHT_CONFIG below are the single source of
// truth for the catalog and the hero spotlight. There is NO
// fallback/default configuration anywhere in this file — if
// PRODUCTS is an empty array, the storefront simply shows an
// empty state instead of silently substituting sample data.
//
// Site-wide settings (title, logo, WhatsApp number, support
// contact, categories) live in main.js as STORE_CONFIG, which is
// loaded before this file in index.html.
//
// Edit PRODUCTS / SPOTLIGHT_CONFIG through admin.html — saves
// there overwrite this file directly via the File System Access
// API and leave everything below this data block untouched.
// ============================================================

const PRODUCTS = [
    {
        "id": 1786612213649,
        "name": "Supreme Navy Box Logo Camp Cap",
        "price": 15000,
        "category": "Face Cap",
        "images": [
            "data:image/jpeg;base64,",
            "data:image/jpeg;base64,",
            "data:image/jpeg;base64,"
        ],
        "description": "Classic navy five-panel cap featuring the iconic red Supreme box logo patch embroidered front and center.",
        "rating": 5,
        "reviews": 0,
        "isNew": false
    },
    {
        "id": 1786612331792,
        "name": "Charles Jeffrey Loverboy Chunky Cat-Ear Beanie",
        "price": 10000,
        "category": "Head Warmer",
        "images": [
            "data:image/jpeg;base64,"
        ],
        "description": "Cream ribbed knit beanie featuring playful pointed cat ears and a branded front woven logo patch.",
        "rating": 5,
        "reviews": 0,
        "isNew": false
    },
    {
        "id": 1786612394122,
        "name": "New Era Oakland Athletics City Patch 59FIFTY Fitted Cap",
        "price": 15000,
        "category": "Face Cap",
        "images": [
            "data:image/jpeg;base64,"
        ],
        "description": "Green fitted baseball cap with white raised embroidered \"A's\" logo and custom California-themed embroidered patches.",
        "rating": 5,
        "reviews": 0,
        "isNew": false
    }
];

const SPOTLIGHT_CONFIG = {
    "badge": "Featured Spotlight",
    "title": "Supreme Navy Box Logo Camp Cap",
    "price": 15000,
    "images": [
        "data:image/jpeg;base64,",
        "data:image/jpeg;base64,",
        "data:image/jpeg;base64,"
    ]
};

// Global Slides Tracker
let cardImageIndexes = {};
let heroSpotlightIndex = 0;
let modalImageIndex = 0;

// State Management
let cart = [];
let wishlist = [];
let activeCategory = 'All';
let searchQuery = '';

// Initialize App
document.addEventListener('DOMContentLoaded', () => {
    if ('serviceWorker' in navigator) {
        navigator.serviceWorker.register('sw.js').catch(() => {});
    }
    applySiteSettings();
    renderSpotlightHero();
    renderCategoriesUI();
    applyFilters();
    updateCartUI();
});

function applySiteSettings() {
    document.title = `${STORE_CONFIG.siteTitle} — Modern E-Commerce`;

    // Two-tone title: first word plain, remainder in brand color —
    // matches the original hand-authored markup's look.
    const spaceIdx = STORE_CONFIG.siteTitle.indexOf(' ');
    const first = spaceIdx === -1 ? STORE_CONFIG.siteTitle : STORE_CONFIG.siteTitle.slice(0, spaceIdx);
    const rest = spaceIdx === -1 ? '' : STORE_CONFIG.siteTitle.slice(spaceIdx + 1);
    document.querySelectorAll('.site-title-text').forEach(el => {
        el.innerHTML = `${first}${rest ? `<span class="text-brand-600">${rest}</span>` : ''}`;
    });

    document.querySelectorAll('.site-logo-image').forEach(el => {
        if (STORE_CONFIG.siteLogoImage) el.style.backgroundImage = `url('${STORE_CONFIG.siteLogoImage}')`;
    });
    document.querySelectorAll('a.site-logo-link').forEach(el => {
        if (STORE_CONFIG.siteLogoImage) el.setAttribute('href', STORE_CONFIG.siteLogoImage);
    });

    const footerEmail = document.getElementById('footerSupportEmail');
    if (footerEmail) {
        if (STORE_CONFIG.supportEmail) {
            footerEmail.href = `mailto:${STORE_CONFIG.supportEmail}`;
            footerEmail.textContent = STORE_CONFIG.supportEmail;
            footerEmail.closest('li')?.classList.remove('hidden');
        } else {
            footerEmail.closest('li')?.classList.add('hidden');
        }
    }
    const footerPhone = document.getElementById('footerSupportPhone');
    if (footerPhone) {
        if (STORE_CONFIG.supportPhone) {
            footerPhone.href = `tel:${STORE_CONFIG.supportPhone.replace(/[^0-9+]/g, '')}`;
            footerPhone.textContent = STORE_CONFIG.supportPhone;
            footerPhone.closest('li')?.classList.remove('hidden');
        } else {
            footerPhone.closest('li')?.classList.add('hidden');
        }
    }
}

function renderSpotlightHero() {
    const images = (SPOTLIGHT_CONFIG.images && SPOTLIGHT_CONFIG.images.length) ? SPOTLIGHT_CONFIG.images : [];

    const heroImg = document.querySelector('#heroSpotlightImage');
    const heroTitle = document.querySelector('#heroSpotlightTitle');
    const heroBadge = document.querySelector('#heroSpotlightBadge');
    const heroPrice = document.querySelector('#heroSpotlightPrice');
    const heroDots = document.querySelector('#heroSpotlightDots');
    const heroContainer = document.querySelector('#heroSpotlightContainer');

    if (images.length === 0) {
        if (heroContainer) heroContainer.classList.add('hidden');
        return;
    }
    if (heroContainer) heroContainer.classList.remove('hidden');

    if (heroImg) heroImg.src = images[heroSpotlightIndex % images.length];
    if (heroTitle) heroTitle.innerText = SPOTLIGHT_CONFIG.title || '';
    if (heroBadge) heroBadge.innerText = SPOTLIGHT_CONFIG.badge || '';
    if (heroPrice) heroPrice.innerText = `₦${Number(SPOTLIGHT_CONFIG.price || 0).toLocaleString()}`;

    if (heroDots) {
        heroDots.innerHTML = images.map((_, i) => `
            <button onclick="setHeroSpotlightSlide(${i})" class="w-2 h-2 rounded-full transition-all ${i === heroSpotlightIndex ? 'bg-white w-5' : 'bg-white/50'}"></button>
        `).join('');
    }
}

function slideHeroSpotlight(direction) {
    const images = SPOTLIGHT_CONFIG.images || [];
    if (images.length === 0) return;

    heroSpotlightIndex = (heroSpotlightIndex + direction + images.length) % images.length;
    renderSpotlightHero();
}

function setHeroSpotlightSlide(index) {
    heroSpotlightIndex = index;
    renderSpotlightHero();
}

// Swipe-to-change-image handling for the hero featured spotlight
let heroTouchStartX = 0;

function handleHeroTouchStart(e) {
    heroTouchStartX = e.changedTouches[0].screenX;
}

function handleHeroTouchEnd(e) {
    const touchEndX = e.changedTouches[0].screenX;
    const delta = touchEndX - heroTouchStartX;
    const swipeThreshold = 40;
    if (Math.abs(delta) > swipeThreshold) {
        if (delta < 0) {
            slideHeroSpotlight(1);
        } else {
            slideHeroSpotlight(-1);
        }
    }
}

function renderCategoriesUI() {
    const container = document.getElementById('categories-section');
    if (!container) return;

    const categories = ['All', ...(STORE_CONFIG.categories || [])];
    container.innerHTML = categories.map(cat => `
        <button onclick="filterCategory('${cat}')" class="cat-btn ${cat === activeCategory ? 'active bg-brand-600 text-white border-brand-600' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-100'} border px-4 py-2 rounded-xl text-sm font-medium whitespace-nowrap transition-all shadow-sm">
            ${cat === 'All' ? 'All Items' : cat}
        </button>
    `).join('');

    const footerList = document.getElementById('footerCategoriesList');
    if (footerList) {
        footerList.innerHTML = (STORE_CONFIG.categories || []).map(cat => `
            <li><a href="#" onclick="filterCategory('${cat}')" class="hover:text-white transition-colors">${cat}</a></li>
        `).join('');
    }
}

function getFilteredProducts() {
    return PRODUCTS.filter(product => {
        const matchesCategory = activeCategory === 'All' || product.category === activeCategory;
        const matchesSearch = product.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                              product.description.toLowerCase().includes(searchQuery.toLowerCase());

        const priceFilter = document.getElementById('priceFilter')?.value || 'all';
        let matchesPrice = true;
        if (priceFilter === 'under50') matchesPrice = product.price < 50000;
        else if (priceFilter === '50to150') matchesPrice = product.price >= 50000 && product.price <= 150000;
        else if (priceFilter === 'over150') matchesPrice = product.price > 150000;

        return matchesCategory && matchesSearch && matchesPrice;
    });
}

function applyFilters() {
    let filtered = getFilteredProducts();
    const sortBy = document.getElementById('sortSelect')?.value;

    if (sortBy === 'low-high') {
        filtered.sort((a, b) => a.price - b.price);
    } else if (sortBy === 'high-low') {
        filtered.sort((a, b) => b.price - a.price);
    } else if (sortBy === 'rating') {
        filtered.sort((a, b) => b.rating - a.rating);
    }

    renderProducts(filtered);
}

function filterCategory(category) {
    activeCategory = category;
    renderCategoriesUI();
    applyFilters();
}

function handleSearch(isMobile = false) {
    const inputId = isMobile ? 'mobileSearchInput' : 'searchInput';
    searchQuery = document.getElementById(inputId).value;
    applyFilters();
}

function resetFilters() {
    searchQuery = '';
    activeCategory = 'All';
    if(document.getElementById('searchInput')) document.getElementById('searchInput').value = '';
    if(document.getElementById('mobileSearchInput')) document.getElementById('mobileSearchInput').value = '';
    if(document.getElementById('priceFilter')) document.getElementById('priceFilter').value = 'all';
    if(document.getElementById('sortSelect')) document.getElementById('sortSelect').value = 'featured';
    filterCategory('All');
}

// Render Cards with 3-Image Slide Capability
function renderProducts(items) {
    const grid = document.getElementById('productGrid');
    const emptyState = document.getElementById('emptyState');
    if (!grid) return;

    if (items.length === 0) {
        grid.innerHTML = '';
        if(emptyState) emptyState.classList.remove('hidden');
        return;
    }

    if(emptyState) emptyState.classList.add('hidden');
    grid.innerHTML = items.map(product => {
        const isWishlisted = wishlist.includes(product.id);
        const images = product.images && product.images.length ? product.images : ['https://via.placeholder.com/400'];
        const currentIdx = cardImageIndexes[product.id] || 0;

        return `
        <div class="group bg-white border border-slate-200/80 rounded-2xl overflow-hidden hover:shadow-xl hover:-translate-y-1 transition-all duration-300 flex flex-col justify-between">
            <div class="relative bg-slate-100 aspect-square overflow-hidden cursor-pointer" onclick="openProductModal(${product.id})" ontouchstart="handleCardTouchStart(event, ${product.id})" ontouchend="handleCardTouchEnd(event, ${product.id})">
                <img 
                    id="card-img-${product.id}"
                    src="${images[currentIdx]}" 
                    alt="${product.name}" 
                    class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                    onerror="this.src='https://via.placeholder.com/400x400?text=No+Image'"
                >
                ${product.isNew ? `<span class="absolute top-3 left-3 bg-brand-600 text-white text-[10px] font-extrabold px-2.5 py-1 rounded-md uppercase tracking-wider z-10">New</span>` : ''}
                
                <button onclick="event.stopPropagation(); toggleWishlist(${product.id})" class="absolute top-3 right-3 w-8 h-8 rounded-full bg-white/90 backdrop-blur-sm flex items-center justify-center text-slate-600 hover:text-rose-500 transition-all shadow-sm z-10">
                    <i class="${isWishlisted ? 'fa-solid text-rose-500' : 'fa-regular'} fa-heart text-sm"></i>
                </button>

                <!-- 3-Image Swipe (touch) indicator dots -->
                ${images.length > 1 ? `
                    <div id="card-dots-${product.id}" class="absolute bottom-2 left-1/2 -translate-x-1/2 flex gap-1.5 z-10">
                        ${images.map((_, i) => `
                            <span class="w-1.5 h-1.5 rounded-full ${i === currentIdx ? 'bg-brand-600 w-3' : 'bg-white/70'} transition-all"></span>
                        `).join('')}
                    </div>
                ` : ''}
            </div>

            <div class="p-5 flex-grow flex flex-col justify-between">
                <div>
                    <div class="flex items-center justify-between text-xs text-slate-400 mb-1">
                        <span>${product.category}</span>
                        <span class="flex items-center gap-1 text-amber-500 font-semibold">
                            <i class="fa-solid fa-star text-[10px]"></i> ${product.rating || 5.0} (${product.reviews || 0})
                        </span>
                    </div>
                    <h3 onclick="openProductModal(${product.id})" class="font-bold text-slate-900 text-base leading-snug group-hover:text-brand-600 cursor-pointer transition-colors line-clamp-1">
                        ${product.name}
                    </h3>
                    <p class="text-xs text-slate-500 mt-1 line-clamp-2">${product.description}</p>
                </div>

                <div class="mt-4 pt-3 border-t border-slate-100 flex items-center justify-between">
                    <div>
                        <span class="text-xs text-slate-400 font-medium block">Price</span>
                        <span class="text-lg font-extrabold text-slate-900">₦${Number(product.price).toLocaleString()}</span>
                    </div>
                    <button onclick="addToCart(${product.id})" class="px-4 py-2 bg-slate-900 hover:bg-brand-600 text-white rounded-xl text-sm font-semibold transition-all flex items-center gap-2 shadow-sm active:scale-95">
                        <i class="fa-solid fa-cart-plus"></i> Add
                    </button>
                </div>
            </div>
        </div>
    `}).join('');
}

// Swipe-to-change-image handling for product cards
let cardTouchStartX = 0;

function handleCardTouchStart(e, productId) {
    cardTouchStartX = e.changedTouches[0].screenX;
}

function handleCardTouchEnd(e, productId) {
    const touchEndX = e.changedTouches[0].screenX;
    const delta = touchEndX - cardTouchStartX;
    const swipeThreshold = 40;
    if (Math.abs(delta) > swipeThreshold) {
        e.stopPropagation();
        if (delta < 0) {
            slideCardImage(productId, 1);
        } else {
            slideCardImage(productId, -1);
        }
    }
}

function slideCardImage(productId, direction) {
    const product = PRODUCTS.find(p => p.id === productId);
    if (!product) return;
    const images = product.images && product.images.length ? product.images : ['https://via.placeholder.com/400'];

    let current = cardImageIndexes[productId] || 0;
    current = (current + direction + images.length) % images.length;
    cardImageIndexes[productId] = current;

    const imgEl = document.getElementById(`card-img-${productId}`);
    if (imgEl) imgEl.src = images[current];

    const dotsEl = document.getElementById(`card-dots-${productId}`);
    if (dotsEl) {
        dotsEl.innerHTML = images.map((_, i) => `
            <span class="w-1.5 h-1.5 rounded-full ${i === current ? 'bg-brand-600 w-3' : 'bg-white/70'} transition-all"></span>
        `).join('');
    }
}

// Cart Drawer Operations
function toggleCartDrawer() {
    const drawer = document.getElementById('cartDrawer');
    const overlay = document.getElementById('cartDrawerOverlay');
    if(!drawer || !overlay) return;
    
    const isOpen = !drawer.classList.contains('translate-x-full');
    if (isOpen) {
        drawer.classList.add('translate-x-full');
        overlay.classList.add('opacity-0', 'pointer-events-none');
    } else {
        drawer.classList.remove('translate-x-full');
        overlay.classList.remove('opacity-0', 'pointer-events-none');
    }
}

function addToCart(productId) {
    const product = PRODUCTS.find(p => p.id === productId);
    if (!product) return;
    const existingItem = cart.find(item => item.id === productId);

    if (existingItem) {
        existingItem.quantity += 1;
    } else {
        cart.push({ ...product, quantity: 1 });
    }

    updateCartUI();
    showToast(`Added <strong>${product.name}</strong> to cart!`);
}

function updateQuantity(productId, delta) {
    const item = cart.find(i => i.id === productId);
    if (!item) return;

    item.quantity += delta;
    if (item.quantity <= 0) {
        cart = cart.filter(i => i.id !== productId);
    }

    updateCartUI();
}

function removeFromCart(productId) {
    cart = cart.filter(i => i.id !== productId);
    updateCartUI();
    showToast("Item removed from cart");
}

function updateCartUI() {
    const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const shipping = subtotal > 100000 || subtotal === 0 ? 0 : 2500;
    const tax = subtotal * 0; // Tax disabled (0%)
    const grandTotal = subtotal + shipping + tax;

    if(document.getElementById('cartBadge')) document.getElementById('cartBadge').innerText = totalItems;
    if(document.getElementById('drawerCountBadge')) document.getElementById('drawerCountBadge').innerText = `${totalItems} items`;
    if(document.getElementById('cartTotalHeader')) document.getElementById('cartTotalHeader').innerText = `₦${subtotal.toLocaleString()}`;

    const list = document.getElementById('cartItemsList');
    const emptyState = document.getElementById('cartEmptyState');
    const cartFooter = document.getElementById('cartFooter');

    if (cart.length === 0) {
        if(list) list.innerHTML = '';
        if(emptyState) emptyState.classList.remove('hidden');
        if(cartFooter) cartFooter.classList.add('hidden');
    } else {
        if(emptyState) emptyState.classList.add('hidden');
        if(cartFooter) cartFooter.classList.remove('hidden');

        if(list) {
            list.innerHTML = cart.map(item => {
                const img = (item.images && item.images[0]) ? item.images[0] : 'https://via.placeholder.com/100';
                return `
                <div class="flex items-center gap-3 pt-3">
                    <img src="${img}" alt="${item.name}" class="w-16 h-16 object-cover rounded-xl bg-slate-100 flex-shrink-0" onerror="this.src='https://via.placeholder.com/100'">
                    <div class="flex-grow min-w-0">
                        <h4 class="font-bold text-sm text-slate-900 truncate">${item.name}</h4>
                        <p class="text-xs text-brand-600 font-semibold mt-0.5">₦${Number(item.price).toLocaleString()}</p>
                        
                        <div class="flex items-center gap-2 mt-2">
                            <div class="flex items-center border border-slate-200 rounded-lg bg-slate-50">
                                <button onclick="updateQuantity(${item.id}, -1)" class="w-6 h-6 flex items-center justify-center text-slate-500 hover:text-slate-900">-</button>
                                <span class="text-xs font-semibold px-2">${item.quantity}</span>
                                <button onclick="updateQuantity(${item.id}, 1)" class="w-6 h-6 flex items-center justify-center text-slate-500 hover:text-slate-900">+</button>
                            </div>
                        </div>
                    </div>
                    <button onclick="removeFromCart(${item.id})" class="text-slate-300 hover:text-rose-500 p-1">
                        <i class="fa-solid fa-trash-can text-sm"></i>
                    </button>
                </div>
            `}).join('');
        }
    }

    if(document.getElementById('cartSubtotal')) document.getElementById('cartSubtotal').innerText = `₦${subtotal.toLocaleString()}`;
    if(document.getElementById('cartShipping')) document.getElementById('cartShipping').innerText = shipping === 0 ? 'FREE' : `₦${shipping.toLocaleString()}`;
    if(document.getElementById('cartTax')) document.getElementById('cartTax').innerText = `₦${tax.toLocaleString()}`;
    if(document.getElementById('cartGrandTotal')) document.getElementById('cartGrandTotal').innerText = `₦${grandTotal.toLocaleString()}`;
}

function checkoutViaWhatsApp() {
    if (cart.length === 0) return;

    if (!STORE_CONFIG.whatsappPhone) {
        showToast("No WhatsApp order number configured yet.");
        return;
    }

    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const shipping = subtotal > 100000 || subtotal === 0 ? 0 : 2500;
    const tax = subtotal * 0;
    const grandTotal = subtotal + shipping + tax;

    let text = `🛒 *New Order from ${STORE_CONFIG.siteTitle}*\n\n`;
    text += `*Order Items:*\n`;
    cart.forEach((item, idx) => {
        text += `${idx + 1}. *${item.name}* (x${item.quantity}) - ₦${(item.price * item.quantity).toLocaleString()}\n`;
    });

    text += `\n----------------------------\n`;
    text += `*Subtotal:* ₦${subtotal.toLocaleString()}\n`;
    text += `*Shipping:* ${shipping === 0 ? 'FREE' : '₦' + shipping.toLocaleString()}\n`;
    text += `*Tax (0%):* ₦${tax.toLocaleString()}\n`;
    text += `*Total Amount:* ₦${grandTotal.toLocaleString()}\n`;
    text += `----------------------------\n`;
    text += `Please process my order. Thank you!`;

    const encodedText = encodeURIComponent(text);
    const phoneNumber = STORE_CONFIG.whatsappPhone.replace(/[^0-9]/g, '');
    const whatsappUrl = `https://wa.me/${phoneNumber}?text=${encodedText}`;

    window.open(whatsappUrl, '_blank');
}

function toggleWishlist(productId) {
    const idx = wishlist.indexOf(productId);
    if (idx > -1) {
        wishlist.splice(idx, 1);
        showToast("Removed from wishlist");
    } else {
        wishlist.push(productId);
        showToast("Saved to your wishlist!");
    }
    
    const badge = document.getElementById('wishlistBadge');
    if (badge) {
        if (wishlist.length > 0) {
            badge.innerText = wishlist.length;
            badge.classList.remove('hidden');
        } else {
            badge.classList.add('hidden');
        }
    }

    applyFilters();
}

// Modal View Pop-Up with 3-Image Slider
let currentModalProductId = null;

function openProductModal(productId) {
    const product = PRODUCTS.find(p => p.id === productId);
    if(!product) return;

    currentModalProductId = productId;
    modalImageIndex = 0;

    renderModalContent(product);

    const modal = document.getElementById('productModal');
    const card = document.getElementById('productModalCard');

    if(modal && card) {
        modal.classList.remove('opacity-0', 'pointer-events-none');
        card.classList.remove('scale-95');
    }
}

function renderModalContent(product) {
    const container = document.getElementById('productModalContent');
    if (!container) return;

    const images = product.images && product.images.length ? product.images : ['https://via.placeholder.com/400'];

    container.innerHTML = `
        <div class="relative bg-slate-100 aspect-square flex items-center justify-center overflow-hidden" ontouchstart="handleModalTouchStart(event)" ontouchend="handleModalTouchEnd(event)">
            <img id="modalProductImage" src="${images[modalImageIndex]}" alt="${product.name}" class="w-full h-full object-cover" onerror="this.src='https://via.placeholder.com/400'">
            
            ${images.length > 1 ? `
                <div class="absolute bottom-3 left-1/2 -translate-x-1/2 flex gap-1.5 z-10">
                    ${images.map((_, i) => `
                        <button onclick="setModalImage(${i})" class="w-2 h-2 rounded-full ${i === modalImageIndex ? 'bg-brand-600 w-4' : 'bg-white/80'} transition-all"></button>
                    `).join('')}
                </div>
            ` : ''}
        </div>
        <div class="p-6 sm:p-8 flex flex-col justify-between">
            <div>
                <span class="text-xs font-semibold uppercase tracking-wider text-brand-600 mb-1 block">${product.category}</span>
                <h2 class="text-2xl font-bold text-slate-900 mb-2">${product.name}</h2>
                <div class="flex items-center gap-2 mb-4 text-xs text-amber-500 font-bold">
                    <div class="flex"><i class="fa-solid fa-star"></i><i class="fa-solid fa-star"></i><i class="fa-solid fa-star"></i><i class="fa-solid fa-star"></i><i class="fa-solid fa-star"></i></div>
                    <span class="text-slate-500 font-normal">(${product.reviews || 0} reviews)</span>
                </div>
                <p class="text-sm text-slate-600 leading-relaxed mb-6">${product.description}</p>
            </div>

            <div>
                <div class="text-3xl font-extrabold text-slate-900 mb-6">₦${Number(product.price).toLocaleString()}</div>
                <div class="flex gap-3">
                    <button onclick="addToCart(${product.id}); closeProductModal()" class="flex-grow py-3 bg-brand-600 hover:bg-brand-700 text-white font-bold rounded-xl transition-all shadow-md flex items-center justify-center gap-2 text-sm">
                        <i class="fa-solid fa-bag-shopping"></i> Add To Cart
                    </button>
                </div>
            </div>
        </div>
    `;
}

// Swipe-to-change-image handling for the product modal
let modalTouchStartX = 0;

function handleModalTouchStart(e) {
    modalTouchStartX = e.changedTouches[0].screenX;
}

function handleModalTouchEnd(e) {
    const touchEndX = e.changedTouches[0].screenX;
    const delta = touchEndX - modalTouchStartX;
    const swipeThreshold = 40;
    if (Math.abs(delta) > swipeThreshold) {
        if (delta < 0) {
            slideModalImage(1);
        } else {
            slideModalImage(-1);
        }
    }
}

function slideModalImage(direction) {
    const product = PRODUCTS.find(p => p.id === currentModalProductId);
    if (!product) return;
    const images = product.images && product.images.length ? product.images : ['https://via.placeholder.com/400'];

    modalImageIndex = (modalImageIndex + direction + images.length) % images.length;
    renderModalContent(product);
}

function setModalImage(index) {
    const product = PRODUCTS.find(p => p.id === currentModalProductId);
    if (!product) return;

    modalImageIndex = index;
    renderModalContent(product);
}

function closeProductModal() {
    const modal = document.getElementById('productModal');
    const card = document.getElementById('productModalCard');
    if(modal && card) {
        modal.classList.add('opacity-0', 'pointer-events-none');
        card.classList.add('scale-95');
    }
}

function showToast(message) {
    const container = document.getElementById('toastContainer');
    if (!container) return;
    
    const toast = document.createElement('div');
    toast.className = 'bg-slate-900 text-white text-sm px-4 py-3 rounded-xl shadow-xl flex items-center gap-3 border border-slate-700 toast-enter';
    toast.innerHTML = `<i class="fa-solid fa-circle-check text-brand-400"></i> <span>${message}</span>`;
    
    container.appendChild(toast);

    setTimeout(() => toast.classList.add('toast-enter-active'), 10);
    setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translateY(100%)';
        toast.style.transition = 'all 0.3s ease';
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}
